# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import OutsideHoursError, find_gaps
from hourglass.errors import ProjectError

HOURS = parse_span("09:00-17:00")


def gaps_for(*texts):
    spans = [parse_span(text) for text in texts]
    return find_gaps(spans, HOURS)


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        result = gaps_for("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            result, ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        result = gaps_for("10:00-16:00")
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)",
            "gap 16:00-17:00 (60 min)"
        ])

    def test_overlap_and_touch_leave_no_gap(self):
        result = gaps_for(
            "09:00-13:00",
            "12:00-15:00",
            "15:00-17:00"
        )
        self.assertEqual(result, [])

    def test_nobody_working_is_a_gap(self):
        result = gaps_for()
        self.assertEqual(
            result, ["gap 09:00-17:00 (480 min)"]
        )

    def test_unsorted_input(self):
        result = gaps_for("14:00-17:00", "09:00-11:00")
        self.assertEqual(
            result, ["gap 11:00-14:00 (180 min)"]
        )


class OutsideHoursTests(unittest.TestCase):
    def test_starting_early_raises(self):
        with self.assertRaises(OutsideHoursError):
            gaps_for("08:00-12:00")

    def test_ending_late_raises(self):
        with self.assertRaises(OutsideHoursError):
            gaps_for("09:00-18:00")

    def test_is_a_project_error(self):
        with self.assertRaises(ProjectError):
            gaps_for("07:00-08:00")
